+/* Deletion and recovery controls: keep the interaction area readable and reachable at every viewport. */
+.planned-payment-panel, .import-history { min-width: 0; }
+.planned-payment-list { display: grid; margin-top: 8px; }
+.planned-payment-row { display: grid; grid-template-columns: minmax(0, 1fr) minmax(112px, auto) 44px; align-items: center; gap: 12px; min-width: 0; padding: 12px 0; border-bottom: 1px solid rgba(120, 157, 198, .13); }
