+.planned-payment-row > div, .planned-payment-row strong, .planned-payment-row span { min-width: 0; }
+.planned-payment-row strong, .planned-payment-row span { display: block; overflow-wrap: anywhere; word-break: break-word; }
+.planned-payment-row strong { color: var(--text); font-size: 12px; }
+.planned-payment-row span { margin-top: 4px; color: var(--muted); font-size: 10px; }
+.planned-payment-row > b { color: var(--text); font-size: 12px; text-align: right; overflow-wrap: anywhere; word-break: break-word; }
+.watchlist-card-actions { display: flex; align-items: center; justify-content: flex-end; gap: 8px; min-width: 0; }
+.import-review-row { grid-template-columns: minmax(0, 1fr) auto; }
