+
+/* Keep every primary destination reachable on a phone without horizontal scrolling. */
+@media (max-width: 620px) {
+  html { min-width: 0; }
+  .sidebar { min-height: 154px; height: auto; padding: 7px 10px; }
+  .sidebar nav { grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 3px; }
+  .sidebar nav button,
+  .sidebar nav button:nth-child(n) { display: grid !important; min-width: 0; min-height: 44px; padding: 5px 2px; }
+  .sidebar nav button span { font-size: 7px; line-height: 1.15; white-space: normal; overflow-wrap: anywhere; }
+  .main-content { padding-bottom: 178px; }
